import{_ as t,o,c as a,a8 as s}from"./chunks/framework.R_sesYpn.js";const u=JSON.parse('{"title":"Collocations","description":"","frontmatter":{},"headers":[],"relativePath":"server/rest-api/search/collocations.md","filePath":"server/030_rest-api/010_search/025_collocations.md","lastUpdated":1780306956000}'),i={name:"server/rest-api/search/collocations.md"};function n(r,e,l,c,d,p){return o(),a("div",null,[...e[0]||(e[0]=[s(`<h1 id="collocations" tabindex="-1">Collocations <a class="header-anchor" href="#collocations" aria-label="Permalink to &quot;Collocations&quot;">​</a></h1> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>A <em>collocation</em> is a series of words or terms that co-occur more often than would be expected by chance. For example, <em>bark</em> and <em>yap</em> are collocates of the keyword <em>dog</em>.</p> <p>Collocations in BlackLab can be proximity-based (i.e. words that occur within 5 positions of <em>dog</em>) or relation-based (i.e. words that have some relation with <em>dog</em>).</p> <p>You can find collocations using a regular <code>/hits</code> request with the <code>group</code> parameter, but there is also a <code>/collocations</code> endpoint that makes it a bit more convenient. It takes the components that make up a collocation request and constructs the correct query, grouping property, and group scorer configuration.</p> <p><strong>URL</strong></p> <ul><li><code>/blacklab-server/&lt;corpus-name&gt;/collocations</code> (API <code>v5</code>)</li> <li><code>/blacklab-server/corpora/&lt;corpus-name&gt;/collocations</code> (future API <code>v5</code>)</li></ul> <p><strong>Method</strong> : <code>GET</code></p> <h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4> <p>Only <code>patt</code> is required; other parameters are optional.</p> <table tabindex="0"><thead><tr><th>Parameter</th> <th>Description</th></tr></thead> <tbody><tr><td><code>filter</code></td> <td><a href="https://lucene.apache.org/core/8_8_1/queryparser/org/apache/lucene/queryparser/classic/package-summary.html#package.description" target="_blank" rel="noreferrer">Lucene Query Language</a> document filter query, to find collocations in part of the corpus</td></tr> <tr><td><code>patt</code></td> <td><a href="/guide/query-language/">BlackLab Corpus Query Language</a> (BCQL) collocation keyword: the pattern to find collocations for, e.g. <code>[lemma=&quot;dog&quot;]</code> to find collocates of <em>dog(s)</em>.</td></tr> <tr><td><code>collpatt</code></td> <td>Collocate filtering (BCQL) pattern, e.g. <code>[pos=&quot;NOUN&quot;]</code> to find only noun collocates</td></tr> <tr><td><code>colltype</code></td> <td>type of collocations to find: <code>proximity</code> (default) or <code>relsources</code>/<code>reltargets</code> (for relation-based collocations; see below)</td></tr> <tr><td><code>context</code></td> <td>(proximity-based collocations) how close a word has to occur to be considered a collocate. Examples: <code>5</code> gives 5 words around the word, <code>5:10</code> gives 5 before and 10 after. Default: <code>5</code></td></tr> <tr><td><code>reltype</code></td> <td>(relation-based collocations; optional) a specific relation type to match, or a regular expression to filter relation types.</td></tr> <tr><td><code>annotation</code></td> <td>annotation to use for gathering collocates (i.e. annotation to group on). Default: main annotation, usually <code>word</code>.</td></tr> <tr><td><code>sensitive</code></td> <td>whether to group case- and accent-sensitively or not. Default: <code>false</code></td></tr> <tr><td><code>scorertype</code></td> <td>collocations found will be scored. This gives the hit group scorer to use. Builtin scorers are <code>coll-dice</code> (default) and <code>coll-salience</code>. See below.</td></tr></tbody></table> <p>In addition to these basic parameters, any parameter that can be added to a regular grouped hits request can be used (e.g. <code>first</code>, <code>number</code>, etc.). See <a href="./find-hits.html">here</a>.</p> <h2 id="scorers" tabindex="-1">Scorers <a class="header-anchor" href="#scorers" aria-label="Permalink to &quot;Scorers&quot;">​</a></h2> <p>Collocation groups are scored using a scorer formula:</p> <table tabindex="0"><thead><tr><th>name</th> <th>description</th> <th>formula</th></tr></thead> <tbody><tr><td><code>coll-dice</code></td> <td>calculates the Dice Coefficient</td> <td><code>(2 * f / (double) (f1 + f2))</code></td></tr> <tr><td><code>coll-salience</code></td> <td>calculates a log-based salience measure</td> <td><code>log(f) * log(f * N / (f1 * f2)) / log(2)</code></td></tr></tbody></table> <p>In the above formulas, <code>f</code> is the frequency of the keyword and collocate occurring together; <code>f1</code> and <code>f2</code> are the frequencies of the words separately; <code>N</code> is the total corpus size (or total cardinality of the relation type you searched for).</p> <p>You can also use hit group scorers with a regular grouped <code>/hits</code> request. In this case, you should pass the <code>scorer</code> parameter with this JSON structure (commented for clarity):</p> <div class="language-jsonc vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">jsonc</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // id of the scorer to instantiate</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;coll-dice&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // document filter (if any; Lucene query language)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;filter&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;title:sea&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // keyword BCQL pattern (used to determine keyword frequency)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;patt&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">boot</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // relation type filter (if any, and if relation-based collocations) </span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;reltype&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;nsubj&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // annotation used for grouping</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;annotation&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;word&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  </span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  // whether grouping was (case- and accent-)sensitive or not</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;sensitive&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>You can implement a custom collocation scorer by writing a plugin of type <code>HitGroupScorer</code>. See <a href="/development/customization/">plugins</a>. Note that in the future, other types of hit group scorer might be added, but currently, collocation scorers are the only possible type.</p> <h2 id="equivalent-hits-requests" tabindex="-1">Equivalent /hits requests <a class="header-anchor" href="#equivalent-hits-requests" aria-label="Permalink to &quot;Equivalent /hits requests&quot;">​</a></h2> <p><code>/collocations</code> is just a convenience endpoint that performs a regular hits grouping. It exists because the <code>/hits</code> URL requires the user to understand the specific BCQL query needed, and the scorer configuration can be a bit cryptic.</p> <h3 id="proximity-based" tabindex="-1">Proximity-based <a class="header-anchor" href="#proximity-based" aria-label="Permalink to &quot;Proximity-based&quot;">​</a></h3> <p>This proximity collocations request (shown without URL encoding for readability):</p> <pre><code>/CORPUSNAME/collocations?
    patt=&quot;boot&quot;&amp;
    collpatt=[pos=&quot;N.*&quot;]&amp;
    colltype=proximity&amp;
    context=3:4&amp;
    annotation=word&amp;
    sensitive=false&amp;
    scorertype=coll-dice
</code></pre> <p>is exactly equivalent to this (shorter but more cryptic) grouped hits request:</p> <pre><code>/CORPUSNAME/hits?
    patt=meet([pos=&quot;N.*&quot;],&quot;boot&quot;,-3,4)&amp;
    group=hit:word:i&amp;
    scorer={&quot;id&quot;:&quot;coll-dice&quot;,&quot;patt&quot;:&quot;\\&quot;boot\\&quot;&quot;,&quot;annotation&quot;:&quot;word&quot;,&quot;sensitive&quot;:false}
</code></pre> <h3 id="relation-based" tabindex="-1">Relation-based <a class="header-anchor" href="#relation-based" aria-label="Permalink to &quot;Relation-based&quot;">​</a></h3> <p>This proximity collocations request (shown without URL encoding for readability):</p> <pre><code>/CORPUSNAME/collocations?
    patt=&quot;boot&quot;&amp;
    collpatt=[pos=&quot;N.*&quot;]&amp;
    colltype=reltargets&amp;
    reltype=nsubj&amp;
    annotation=word&amp;
    sensitive=false&amp;
    scorertype=coll-dice
</code></pre> <p>is exactly equivalent to this grouped hits request:</p> <pre><code>/CORPUSNAME/hits?
    patt=rspan(&quot;boot&quot; -nsubj-&gt; [pos=&quot;N.*&quot;], &quot;target&quot;)&amp;
    group=hit:word:i&amp;
    scorer={&quot;id&quot;:&quot;coll-dice&quot;,&quot;patt&quot;:&quot;\\&quot;boot\\&quot;&quot;,&quot;annotation&quot;:&quot;word&quot;,&quot;sensitive&quot;:false}
</code></pre> <h2 id="success-response" tabindex="-1">Success Response <a class="header-anchor" href="#success-response" aria-label="Permalink to &quot;Success Response&quot;">​</a></h2> <p><strong>HTTP response code</strong>: <code>200 OK</code></p> <p>The response will have the same structure as a <code>/hits</code> request with the <code>group</code> parameter. See <a href="./find-hits.html">here</a>.</p>`,66)])])}const k=t(i,[["render",n]]);export{u as __pageData,k as default};
